### 4. Create ModelTrainer service
Create `Services/ModelTrainer.cs`. This service:
- Uses `MLContext(seed: 42)` for reproducibility
- Loads CSV data from `Data/tickets.csv`
- Splits into train/test (test fraction 0.2)
- Builds a pipeline:
  - Featurize Subject and Description with `FeaturizeText`
  - Concatenate text features + Priority into "Features"
  - Map Category to a key label via `MapValueToKey`
  - Use `SdcaMaximumEntropy` multiclass trainer
  - Map key back to value with `MapKeyToValue`
- Trains the model
- Evaluates on test set, logs metrics (MicroAccuracy, MacroAccuracy, LogLoss) using `ILogger`
- Saves the model to `Data/TicketModel.zip`
- Implements `IHostedService` to train on app startup

```csharp
using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainer : IHostedService
{
    private readonly ILogger<ModelTrainer> _logger;
    private readonly string _dataPath;
    private readonly string _modelPath;

    public ModelTrainer(ILogger<ModelTrainer> logger)
    {
        _logger = logger;
        _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        _modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "TicketModel.zip");
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        var mlContext = new MLContext(seed: 42);

        var data = mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training ticket classification model...");
        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation("Model evaluation metrics:");
        _logger.LogInformation("  MicroAccuracy:  {MicroAccuracy:F4}", metrics.MicroAccuracy);
        _logger.LogInformation("  MacroAccuracy:  {MacroAccuracy:F4}", metrics.MacroAccuracy);
        _logger.LogInformation("  LogLoss:        {LogLoss:F4}", metrics.LogLoss);
        _logger.LogInformation("  LogLossReduction: {LogLossReduction:F4}", metrics.LogLossReduction);

        mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {ModelPath}", _modelPath);

        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}
```

